import { z } from 'zod';

import { gameIdentityKind } from './events';

/**
 * Events the FiveM bridge reports to Core (`POST /api/bridge/events`).
 *
 * The bridge signs each request with FIVEM_BRIDGE_SECRET. Identifiers are read
 * server-side by FXServer (`GetPlayerIdentifier`), never taken from a client
 * event, and Core resolves them to a Xenon account using trusted kinds only.
 * `eventId` is generated by the bridge and becomes the idempotency key, so a
 * retried POST records one event.
 */

const identifier = z.object({
  kind: gameIdentityKind,
  value: z
    .string()
    .trim()
    .min(1)
    .max(128)
    .regex(/^[A-Za-z0-9:_.-]+$/),
});
const identifiers = z.array(identifier).min(1).max(16);
const eventId = z.uuid();
const playerName = z.string().trim().max(64);
/** The bridge's `xenon_slug` convar; matches `Server.slug`. */
const serverSlug = z
  .string()
  .trim()
  .min(1)
  .max(64)
  .regex(/^[a-z0-9-]+$/);
const common = { eventId, serverSlug };

export const bridgeEventInput = z.discriminatedUnion('type', [
  z.object({ type: z.literal('PLAYER_CONNECTED'), ...common, identifiers, playerName }),
  z.object({
    type: z.literal('PLAYER_DISCONNECTED'),
    ...common,
    identifiers,
    playerName,
    reason: z.string().trim().max(200),
  }),
  z.object({
    type: z.literal('SERVER_RESTART_SCHEDULED'),
    ...common,
    secondsRemaining: z
      .number()
      .int()
      .min(0)
      .max(24 * 60 * 60),
  }),
  /** A txAdmin ban. Recorded as a FiveM-scope moderation case; it does not ban the Xenon account. */
  z.object({
    type: z.literal('PLAYER_BANNED'),
    ...common,
    identifiers,
    playerName,
    reason: z.string().trim().max(500),
    /** Seconds until expiry; null for a permanent ban. */
    durationSeconds: z.number().int().min(0).nullable(),
    /** txAdmin's action id, for cross-reference. */
    externalRef: z.string().trim().max(64).nullable(),
  }),
]);

export type BridgeEventInput = z.output<typeof bridgeEventInput>;
